Lemma program_old_to_new_35 : program_before_35 -> program_after_35.

Proof. intros rule hlc Σ P. destruct P as [w r g inv heap]. exact (@rule hlc Σ inv heap w r g). Qed.

Lemma program_new_to_old_35 : program_after_35 -> program_before_35.

