Lemma program_old_to_new_85 : program_before_85 -> program_after_85.

Proof. intros rule hlc Σ P. destruct P as [w r g inv heap]. exact (@rule hlc Σ inv heap w r g). Qed.

Lemma program_new_to_old_85 : program_after_85 -> program_before_85.

