Lemma program_old_to_new_292 : program_before_292 -> program_after_292.

Proof. intros rule hlc Σ P. destruct P as [w r g inv heap]. exact (@rule hlc Σ inv heap w r g). Qed.

Lemma program_new_to_old_292 : program_after_292 -> program_before_292.

