Lemma program_old_to_new_381 : program_before_381 -> program_after_381.

Proof. intros rule hlc Σ P. destruct P as [w r g inv heap]. exact (@rule hlc Σ inv heap w r g). Qed.

Lemma program_new_to_old_381 : program_after_381 -> program_before_381.

Proof. intros rule hlc Σ inv heap w r g. exact (@rule hlc Σ {| program_world := w; program_registry := r; program_ge := g; program_inv := inv; program_heap := heap |}). Qed.

