Lemma program_old_to_new_421 : program_before_421 -> program_after_421.

Proof. intros rule hlc Σ P. destruct P as [w r g inv heap]. exact (@rule hlc Σ inv heap w r g). Qed.

Lemma program_new_to_old_421 : program_after_421 -> program_before_421.

